create table if not exists public.federation_remote_engagements (id uuid primary key default gen_random_uuid(), activity_uri text not null unique, object_url text not null, remote_actor_url text not null, interaction_type text not null check (interaction_type in ('like','repost','reply','quote','undo')), payload jsonb not null default '{}'::jsonb, status text not null default 'active' check (status in ('active','undone')), received_at timestamptz not null default now(), updated_at timestamptz not null default now(), expires_at timestamptz);
create index if not exists idx_fed_remote_engagements_object on public.federation_remote_engagements(object_url,interaction_type,status);
